/**
 * DCDS Verified+ provider-neutral identity verification types.
 *
 * This module is deliberately transport- and vendor-independent. It contains
 * no Supabase client, network access, secrets, or persistence.
 */

export type DcdsIdentityDecision =
  | "pending"
  | "verified"
  | "rejected"
  | "requires_review"
  | "suspended"
  | "revoked";

export type ProviderIdentityDecision =
  | "pending"
  | "verified"
  | "rejected"
  | "requires_review";

export interface StartVerificationInput {
  /** Opaque DCDS case identifier generated by trusted server code. */
  caseId: string;
  /** Authenticated applicant identifier; adapters must not expose it unnecessarily. */
  applicantId: string;
  /** ISO 3166-1 alpha-2 country code, validated by the caller and adapter. */
  countryCode: string;
  /** DCDS-owned URL. Concrete adapters must enforce an allowlist. */
  returnUrl: string;
  /** Stable key for safely retrying session creation. */
  idempotencyKey: string;
}

export interface StartVerificationResult {
  providerName: string;
  /** Opaque provider case/session reference; never a government document number. */
  providerReference: string;
  /** Short-lived hosted capture URL. Treat as sensitive and do not log it. */
  hostedUrl: string;
  expiresAt: string;
}

export interface NormalizedProviderOutcome {
  providerReference: string;
  providerEventId?: string;
  decision: ProviderIdentityDecision;
  reasonCode?: string;
  occurredAt: string;
  countryCode?: string;
  documentCategory?: string;
}

export interface VerifyNotificationInput {
  /** Exact, unmodified request bytes used for provider signature validation. */
  rawBody: Uint8Array;
  headers: Record<string, string>;
  receivedAt: string;
}

export interface IdentityProviderAdapter {
  readonly providerName: string;

  startVerification(
    input: StartVerificationInput,
  ): Promise<StartVerificationResult>;

  /**
   * Returns null for invalid, stale, duplicate, unbound, or unsupported events.
   * Domain services must still apply DCDS case-state, reviewer, and entitlement
   * rules before changing an identity decision.
   */
  verifyNotification(
    input: VerifyNotificationInput,
  ): Promise<NormalizedProviderOutcome | null>;

  /** Retrieves a previously validated outcome from the provider. */
  getOutcome(input: {
    providerReference: string;
  }): Promise<NormalizedProviderOutcome>;
}

export type IdentityProviderErrorCode =
  | "INVALID_INPUT"
  | "RETURN_URL_NOT_ALLOWED"
  | "INVALID_SIGNATURE"
  | "STALE_NOTIFICATION"
  | "OUTCOME_NOT_AVAILABLE"
  | "PROVIDER_UNAVAILABLE";

export class IdentityProviderAdapterError extends Error {
  constructor(
    public readonly code: IdentityProviderErrorCode,
    message: string,
    public readonly retryable = false,
  ) {
    super(message);
    this.name = "IdentityProviderAdapterError";
  }
}
